class Solution {
public:
    int minimumDistance(int n, vector<vector<int>>& edges, int s, vector<int>& marked) {
        vector<vector<pair<int,int>>> graph(n);
        for (auto& e : edges) graph[e[0]].push_back({e[1], e[2]});
        vector<long long> dist(n, LLONG_MAX);
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
        dist[s] = 0;
        pq.push({0, s});
        while (!pq.empty()) {
            auto cur = pq.top(); pq.pop();
            if (cur.first != dist[cur.second]) continue;
            for (auto edge : graph[cur.second]) {
                long long next = cur.first + edge.second;
                if (next < dist[edge.first]) {
                    dist[edge.first] = next;
                    pq.push({next, edge.first});
                }
            }
        }
        long long answer = LLONG_MAX;
        for (int v : marked) answer = min(answer, dist[v]);
        return answer == LLONG_MAX ? -1 : (int)answer;
    }
};
